INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-16-2026-05-15-mcp-server-pitfalls-brief-signal#8', '2026-05-16-2026-05-15-mcp-server-pitfalls-brief-signal', 8, 'Codex refinement required',
  '## Codex refinement required

