INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-16-2026-05-16-telegram-telegram-user-9-как-использовать-superpowers-в-codex-signal#6', '2026-05-16-2026-05-16-telegram-telegram-user-9-как-использовать-superpowers-в-codex-signal', 6, 'Noise removed',
