INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-16-youtube-transcript-we-re-introducing-three-audio-models-in-the-api-signal#7', '2026-05-16-youtube-transcript-we-re-introducing-three-audio-models-in-the-api-signal', 7, 'Verification required',
  '## Verification required

- Recheck OpenAI platform docs for current model IDs, API endpoints, pricing, quotas and regional availability.
- Verify whether `preambles`, parallel tool calls and reasoning effort are configured through stable API parameters or prompt/tooling patterns.
- Check privacy, retention and EU data residency requirements before using realtime audio with real user speech.
- Compare with local-first transcription workflow for offline or private audio.', '0885f63ee64a0d576bacf639bee1420a61e1e8900dd509ea943854135d2d1651', 90
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Verification required

