INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-medium-harness-engineering-six-layer-signal#8', '2026-05-17-medium-harness-engineering-six-layer-signal', 8, 'Codex refinement notes',
