INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-06-01-media-transcript-the-7-skills-you-need-to-build-ai-agents-signal#6', '2026-06-01-media-transcript-the-7-skills-you-need-to-build-ai-agents-signal', 6, 'Noise removed',
  '## Noise removed

- Intro/outro, newsletter promotion, repeated motivational framing and timestamped transcript fragments were removed.
- The signal avoids long transcript quotes and preserves only reusable engineering claims.', 'f3047fca83d94d1d38560f4d0b2030cfce7c3edf70eb9bf9236e62422500112b', 40
);
