INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-15-harness-engineering-codex-agents-brief', '02_briefs/2026-05-15-harness-engineering-codex-agents-brief.md', 'brief', 'draft', 'Artifact: source-56805a57-e063-4b1b-b547-4d8a4fbf78b9',
  'Ryan Lopopolo описывает harness engineering как инженерную дисциплину вокруг coding agents: человек больше не должен быть главным производителем кода, а должен проектировать среду, инструкции, guardrails, CI feedback loops, review agents, repo structure и проверяемые acceptance criteria, чтобы агенты могли выполнять полный цикл разработки. Главный сдвиг: implementation становится дешевой и параллелизуемой, а дефицитными ресурсами становятся human time, human/model attention и context window.', 'bcee68e29644ac3c88dee94b7defc66bd55b5a62407c043d07eb335dbe0a367b', '2026-05-15', '2026-06-01', '2026-06-13T21:29:20.393Z'
