INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-15-local-video-to-structured-text-brief', '02_briefs/2026-05-15-local-video-to-structured-text.md', 'brief', 'draft', 'Brief: local-video-to-structured-text',
  'Текст описывает удачный переход от полуавтоматического workflow к локальному агентному workflow: 1. Раньше Codex извлекал аудио из видео через `ffmpeg`. 2. Затем mp3 вручную загружался в AI Studio. 3. Новый эксперимент: Codex локально установил Kesha Voice Kit, распознал аудио и выдал структурированный документ. Главная ценность: сокращение ручных действий и превращение обработки видео в повторяемую агентную операцию на Mac.', '5b5f8f5978dd60d46f1e865928f8353e9e6b6af267efcfe89feb3519513da9ad', '2026-05-15', '2026-05-15', '2026-06-13T21:29:20.393Z'
)
