INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-15-mcp-server-pitfalls-brief', '02_briefs/2026-05-15-mcp-server-pitfalls-brief.md', 'brief', 'draft', 'Brief: mcp-server-pitfalls',
  'Статья Битрикс24 описывает восемь практических проблем MCP-server development. Главный вывод для Techscope: MCP server нельзя проектировать как обычную API-обертку. MCP tool surface является интерфейсом для недетерминированной модели, поэтому инструменты должны быть сценарными, самодостаточными, семантически ясными, безопасными, тестируемыми через model behavior and bounded by context limits.', '6de40784251f8b36d611820aeba4c2c533996ae4fb33a82f972f7b8d0a8bf06d', '2026-05-15', '2026-05-15', '2026-06-13T21:29:20.393Z'
)
