INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-16-openai-realtime-audio-models-voice-agents-brief', '02_briefs/2026-05-16-openai-realtime-audio-models-voice-agents-brief.md', 'brief', 'draft', 'Artifact: source-2b62b642-244f-40f4-9f44-f79c48127324',
  'OpenAI announced three realtime audio models in the API: `GPT-Realtime-2`, `GPT-Realtime-Translate` and `GPT-Realtime-Whisper`. For Techscope, the most useful idea is not simply higher-quality speech. The agent-design signal is that voice agents can now stay in a live conversation while reasoning, calling tools, translating or transcribing in the background. This creates a new design surface for agents: voice UX, preambles, interruption handling, progress updates, live transcript memory, multilingual support and consent/privacy rules.', '386f7ba20f5aec4f1d3860738cb14231f38a98196fd71a064eeb544dc389005e', '2026-05-16', '2026-06-01', '2026-06-13T21:29:20.393Z'
)
