INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-codbash-agent-session-browser-brief', '02_briefs/2026-05-17-codbash-agent-session-browser-brief.md', 'brief', 'draft', 'Brief: Codbash as coding-agent session browser',
  'Codbash is a local browser dashboard for managing AI coding-agent sessions across Claude Code, Codex CLI, Cursor, OpenCode, Kiro, Kilo and Copilot Chat. The Telegram update and screenshots show the product moving from passive session browsing toward a project launcher: projects, default agent selection, new/last session controls, GitHub repo onboarding, grouped history and cost/session analytics. For Techscope, this is interesting because agent work quickly becomes multi-session and multi-runtime. We need observability, resumption and cost visibility before running many parallel agents seriously.', 'cc87e1bfb4951c292198490055d0beda8fbcf8c9e3c842e84c70d292756aea3a', '2026-05-17', '2026-05-17', '2026-06-13T21:29:20.393Z'
)
