INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-codex-mobile-desktop-remote-connection-brief', '02_briefs/2026-05-17-codex-mobile-desktop-remote-connection-brief.md', 'brief', 'draft', 'Artifact: source-5b71202a-56cd-4cf3-89bb-8094bc6b626e',
  'Скриншот показывает, что мобильный Codex/ChatGPT UI уже работает как поверхность управления подключениями: виден существующий `Codex Desktop` host и форма `Add SSH Host`. В сочетании с официальной статьей OpenAI от 2026-05-14 это подтверждает важный UX-сдвиг: Codex можно использовать не только сидя за рабочей машиной, но и как long-running agent, которым пользователь управляет с телефона.', '5628c986851f3ead5b73a4fe6250a5016a1c160b5e3b040b62b1502a17238b38', '2026-05-17', '2026-06-01', '2026-06-13T21:29:20.393Z'
)
