INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-hermes-agent-architecture-brief', '02_briefs/2026-05-17-hermes-agent-architecture-brief.md', 'brief', 'draft', 'Brief: Hermes Agent architecture',
  'Hermes Agent is an open-source, model-agnostic autonomous agent runtime from Nous Research. It is not just a CLI coding assistant; it is closer to a long-running personal agent platform with CLI, gateway, messaging, cron, memory, skills, toolsets, MCP, terminal backends, plugins, session search and optional external memory providers. For Techscope, Hermes is important because it offers a concrete architecture for self-hosted, persistent, multi-surface agents. The strongest patterns are bounded memory, procedural skills, gateway authorization, toolset narrowing, progressive project context discovery and server/VPS operation.', '986a2c201456d557b8580ab95cda22e45e6b5fbeaeb711ddf76adec5c2a82985', '2026-05-17', '2026-05-17', '2026-06-13T21:29:20.393Z'
)
