INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-hermes-agent-setup-brief', '02_briefs/2026-05-17-hermes-agent-setup-brief.md', 'brief', 'draft', 'Artifact: source-db6a0d73-ccfa-4c09-bddf-7332366126d2',
  'The video is useful as a hands-on setup walkthrough for Hermes Agent as an always-on personal agent: VPS or Mac mini, Docker/service persistence, provider keys, Telegram bot, gateway pairing and command approvals. It does not replace official docs and should not be treated as proof that Hermes supersedes OpenClaw. For Techscope, the main value is not the Hostinger path itself. The value is the deployment pattern: start with a working CLI agent, add provider configuration, then expose it through a controlled messaging gateway, with persistent storage and explicit authorization.', '7d93df4a75d495480ddcbefe97b0b426a3e26a37de8ca7ff5acae7c4a149a869', '2026-05-17', '2026-06-01', '2026-06-13T21:29:20.393Z'
)
