INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-mimiclaw-embedded-agent-brief', '02_briefs/2026-05-17-mimiclaw-embedded-agent-brief.md', 'brief', 'draft', 'Artifact: source-b6066dd1-b25a-4a42-a4f6-6377cc8fd5c3',
  'MimiClaw is an OpenClaw-inspired embedded agent that runs the agent control loop on an ESP32-S3 microcontroller instead of a Mac mini, VPS, Linux box or Node/Python runtime. The LLM still runs in the cloud, but the device owns the interaction loop, Telegram/WebSocket channels, memory/session files, tool registry, serial CLI, OTA flow and low-power always-on operation. For Techscope, MimiClaw is valuable as a boundary-case architecture. It shows what survives when an autonomous agent is squeezed into tiny hardware: simple queues, explicit tasks, plain-text memory, narrow tools, constrained config and a very visible security boundary.', '0dc332c093f33a16f401ebc244ce3c1f1ad95a759d56ab9928a0b4926ba2ff23', '2026-05-17', '2026-06-01', '2026-06-13T21:29:20.393Z'
)
