INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-openclaw-hermes-codex-cli-advanced-user-brief', '02_briefs/2026-05-17-openclaw-hermes-codex-cli-advanced-user-brief.md', 'brief', 'draft', 'Artifact: source-1a9cb686-2cd6-4f6d-bb1f-e2335cfb5570',
  'Видео полезно как UX-свидетельство продвинутого пользователя, который не является профессиональным разработчиком, но активно использует агентские системы. Его главный практический вывод: выбор агентской среды для реальной работы определяется не "самым умным" ответом, а стабильностью контура, управлением памятью, стоимостью контекста, прозрачностью tools/skills and recovery after restart.', '7c8bcbf13ea00acfe44a63ce37c53202053e66d6bbc340ccec8c2474f090c8c1', '2026-05-17', '2026-06-01', '2026-06-13T21:29:20.393Z'
)
