INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-openclaw-personal-agent-architecture-brief', '02_briefs/2026-05-17-openclaw-personal-agent-architecture-brief.md', 'brief', 'draft', 'Brief: OpenClaw personal agent architecture',
  'OpenClaw is useful to study not as a single clever prompt, but as a complete personal-agent operating model. Its central pattern is a long-lived local Gateway that owns channels, clients, events and agent runs, while agents are scoped workspaces with their own sessions, auth profiles, skills and memory. This is directly relevant to Techscope because our Telegram ingestion, Obsidian/Markdown memory, expert assessment and future coding-agent orchestration need the same separation between ingress, durable knowledge, agent runtime and tool boundaries.', '355af4e7cffa9d4211f67723b1f5720ea809237bd0d93ef0c7bd5565d1c62826', '2026-05-17', '2026-05-17', '2026-06-13T21:29:20.393Z'
)
