INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-17-skills-vs-mcp-agent-tooling-brief', '02_briefs/2026-05-17-skills-vs-mcp-agent-tooling-brief.md', 'brief', 'draft', 'Artifact: source-f71ffbdf-62d1-436b-b9ff-81e6307fd74c',
  'The useful conclusion is not "Skills killed MCP". Skills and MCP solve adjacent but different problems. MCP is a protocol for exposing external context, tools and services to agents. Skills are portable, progressive-disclosure instructions that tell an agent how to perform a task, often by using local scripts, CLIs, reference files or MCP tools. For Techscope and future coding agents, the practical rule should be: prefer skills for local repeatable workflows and process knowledge; prefer MCP for service integration, OAuth, shared governance, caching, remote/API-agent environments and standardized tool access.', '897d7ea99630befbe786de73843bb31693541985b4a7ebbdb3e8b9af5b93d9b9', '2026-05-17', '2026-06-01', '2026-06-13T21:29:20.393Z'
)
