INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-18-hermes-agent-practical-use-cases-brief', '02_briefs/2026-05-18-hermes-agent-practical-use-cases-brief.md', 'brief', 'processed', 'Artifact: source-82f18a97-472f-4a5c-a189-f87f1e3e27dd',
  'The video is useful because it shows how an advanced operator turns Hermes into a practical team of role agents: coordinator, designer, marketer, researcher, economist, document helper, planner and Codex CLI bridge. The key lesson for Techscope is not a specific Hermes command, but an agent-product pattern: each agent should own a narrow recurring pain, have its own memory and skills, and communicate through a shared map/wiki plus concise human-facing messages.', '9d26494d24ea85ece7b292835f42c34f3378336dfdd51ace7ec6fe25a2a2937d', '2026-05-18', '2026-06-01', '2026-06-13T21:29:20.393Z'
