INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-26-openclaw-expensive-local-ai-brief', '02_briefs/2026-05-26-openclaw-expensive-local-ai-brief.md', 'brief', 'draft', 'Brief: OpenClaw Expensive Local AI',
  'The useful signal is a runtime-placement pattern for agents: do not run every subtask on the most expensive frontier model. Start with strong models while discovering the workflow, then split stable repeated work into cheaper local or small-model routes after measuring quality. This is directly useful for Agents Mother contracts because new agents should specify where each class of inference work runs.', '08fb29b977c545372aa4550d4161902974d62693aa1605caeff787c9471e5b03', '2026-05-26', '2026-05-26', '2026-06-13T21:29:20.393Z'
