INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-26-openclaw-hacked-prompt-injection-brief', '02_briefs/2026-05-26-openclaw-hacked-prompt-injection-brief.md', 'brief', 'draft', 'Artifact: source-511135b7-653f-4147-90c2-b515bc79b59b',
  'The video is a useful adversarial demo for personal agents that read external messages. The main signal is not that one OpenClaw setup survived one attacker. The durable lesson is that email, Telegram, websites, files and media transcripts must be treated as untrusted input. Before such input can affect model instructions, tools, memory or spend, it needs filtering, quota limits, structured extraction, quarantine and human approval gates.', 'e122f1a6d92d49fda780b7fb7af30433bfb0a53dfe17fa847ce5f420805d329a', '2026-05-26', '2026-06-01', '2026-06-13T21:29:20.393Z'
