INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-05-27-hermes-agent-team-operating-model-brief', '02_briefs/2026-05-27-hermes-agent-team-operating-model-brief.md', 'brief', 'draft', 'Brief: Hermes Agent Team Operating Model',
  'The durable idea is to design an agent project as an operating system of specialists, not as one overgrown assistant. A coordinator handles user-facing intake and routing; specialist agents own narrow domains; scheduled reports and daily notes create continuity; a separate reflection agent compares work against goals; heavy coding or long-running tasks can be delegated to a sidecar runtime such as Codex CLI.', '4f603fcb54b2681acf97db2eb6bffa3c21f9ba97ab54511ddaa7f49e1f18eb2e', '2026-05-27', '2026-05-27', '2026-06-13T21:29:20.393Z'
