INSERT INTO documents (id, path, type, status, title, summary, hash, created_at, updated_at, indexed_at)
VALUES (
  '2026-06-11-pi-agent-harness-patterns-brief', '02_briefs/2026-06-11-pi-agent-harness-patterns-brief.md', 'brief', 'draft', 'Brief: Pi agent harness patterns',
  'Pi is a strong reference for future Pritha child-agent design because it demonstrates a small, inspectable coding-agent core surrounded by explicit customization mechanisms: extensions, skills, prompt templates, packages, session branching, compaction, SDK/RPC and a TUI adapter. The most useful lesson is architectural discipline, not direct adoption of Pi as our default runtime. Pritha should preserve a minimal core for each descendant and add capabilities only through contract-selected modules with reviewed provenance and security boundaries.', 'b749430c71234b9ee4eaf357d68992dce00c1d0b6d284e1adf9ef3f1755a43c9', '2026-06-11', '2026-06-11', '2026-06-13T21:29:20.393Z'
)
