INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-16-test-first-agent-workflow-review#11', '2026-05-16-test-first-agent-workflow-review', 11, 'Research Scout',
  '### Research Scout

