INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-hermes-agent-setup-assessment#3', '2026-05-17-hermes-agent-setup-assessment', 3, 'Options',
  '## Options

- Adopt the setup directly.
- Archive it as promotional tutorial content.
- Extract the operational pattern and verify exact commands against current official docs.', 'cfd58dbe1245054a308edf525c27df4b803f69b987a9d1ccaef0db7cc61334ab', 37
);
