INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-hermes-agent-setup-assessment#4', '2026-05-17-hermes-agent-setup-assessment', 4, 'Comparison',
  '## Comparison

| Option | Strengths | Weaknesses | Fit |
| --- | --- | --- | --- |
| Adopt directly | Fast path to a working Hermes gateway | Version drift, sponsored hosting path, high security risk | Poor |
| Archive only | Avoids overreacting to hype | Loses practical deployment lessons | Weak |
| Extract pattern and verify | Preserves useful operational knowledge while controlling risk | Requires a separate experiment | Strong |', 'e207443a00589043e84bc0f443be2a0fe12dbc223d48bc3de344ec2f1412aa6c', 108
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Comparison

| Option | Strengths | Weaknesses | Fit |
| --- | --- | --- | --- |
