INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-17-mimiclaw-embedded-agent-assessment#3', '2026-05-17-mimiclaw-embedded-agent-assessment', 3, 'Options',
  '## Options

- Ignore it as a hardware curiosity.
- Treat it as an immediate deployment target.
- Track it as an embedded-agent architecture reference and possible future experiment.', '1a7e23d1487ec34ff0bce8e87dc6a504744346619ee98e8ec52c9e16cfce7c59', 40
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Options

- Ignore it as a hardware curiosity.
- Treat it as an immediate deployment target.
