INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-and-release-pattern-review#9', '2026-05-28-techscope-quality-and-release-pattern-review', 9, 'Security',
  '### Security

