INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-06-01-agent-connectivity-stack-update-assessment#14', '2026-06-01-agent-connectivity-stack-update-assessment', 14, 'Recommendation',
  '## Recommendation

Update existing standards:

- `agent-tool-integration-selection`: add progressive discovery and code-mode
  orchestration guidance.
- `agent-mcp-connector-lifecycle`: add server cards, registry/discovery,
  Skills Over MCP watch status and dynamic toolset checks.
- Keep Pritha default simple: eager manifests for small agents, discovery layers
  only for tool-heavy or enterprise-facing agents.', 'a6d64e161067c8f0794611b02e49deac7e7e42ccd306b74075856f176000ac20', 64
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Recommendation

