INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-06-01-production-agent-controls-assessment#6', '2026-06-01-production-agent-controls-assessment', 6, 'Techscope Adoption Check',
  '## Techscope Adoption Check

- Techscope/Agents Mother fit: adopt.
- Why: add as a production-readiness lens for child agents, not as a default
  requirement for every simple local agent.
- Implementation cost: medium.
- Operational complexity: medium.
- Current architecture impact: mostly contract/interview/scaffold-readiness
  questions.
- Decision: create a follow-up review or standard section for
  production-control-plane readiness.', '6c6827d7298745bdbbb1e93c606d1d8c9b0f9965ea11ca3b4029a3fc07568e38', 76
);
