INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-06-12-voice-v13-v15-implementation-smoke-voice-session-memory#3', '2026-06-12-voice-v13-v15-implementation-smoke-voice-session-memory', 3, 'Durable Signals',
  '## Durable Signals

- smoke system: Implemented Pritha voice roadmap V13 task detail drawer and recovery API.
- smoke system: Implemented V14 current session recall drawer with search and compact recap.
- smoke system: Implemented V15 curated memory promotion for Pritha, child agents, realtime voice, Codex and memory policy.
- smoke task smoke: Architecture and UI behavior decisions for Pritha voice control should be saved as curated memory without raw transcript.', '074cde594e2135af35c1154d5843de9e62ce1bb1aea7ea1b18907031e2d1250a', 96
);
