INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'agent-creation-harness#5', 'agent-creation-harness', 5, 'Avoid when',
  '## Avoid when

- the request is only a one-off analysis task inside TechScope;
- the user has not agreed on the agent''s purpose and success criteria;
- source freshness or platform semantics cannot be verified;
- the requested agent would require secrets, deployment or external actions that are not explicitly approved.', 'fca9739ea0d926df16648525b203434023b60242377e3ed95aeb717ca5ee16fc', 71
);
