INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'agent-mcp-connector-lifecycle#19', 'agent-mcp-connector-lifecycle', 19, 'Temporal Validity',
  '## Temporal Validity

- Source published: 2026-05-17.
- Source updated: 2026-06-02.
- Source version: Pritha MCP connector lifecycle v3; prior Techscope memory,
  MCP/GitHub MCP references and Codex/Docker/remote MCP source batches reviewed.
- Retrieved: 2026-06-01.
- Verified: 2026-06-02.
- Valid for: Pritha-created agents that may use external MCP servers or
  MCP-style connectors.
- Freshness status: current.
- Temporal status: current.
- Recheck when: MCP spec/auth/tool discovery changes, major clients change MCP
  configuration semantics, registries/catalogs change trust semantics, remote
  MCP auth guidance changes, or a child agent selects a security-sensitive MCP.', 'a36e6660163777479aa82fdfc99bda5e35c8732dcd65b6961cbfe097f48dbbd2', 121
);
