INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'pritha-self-model#3', 'pritha-self-model', 3, 'What Belongs Here',
  '## What Belongs Here

- Pritha identity and mission;
- current capabilities and limits;
- memory architecture;
- child-agent creation lifecycle;
- safety, privacy and governance rules;
- quality gates and self-tests;
- roadmap and self-improvement loop;
- marketing narrative boundaries.', '73475a66a22c16bac5e10bd0d8e2f458f6ecc9daa44ba8aed556fd9b72f3de77', 56
);
