INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'signal-extraction#4', 'signal-extraction', 4, 'Keep',
  '## Keep

- технические claims;
- конкретные практики;
- tool/API/model/library names;
- архитектурные ограничения;
- failure modes;
- security/DX risks;
- eval ideas;
- candidate rules for agents;
- official primary-source links and verification tasks when they are stable reference material, not incoming-material provenance.', '75ba9edf2edefbbb67e0960971cc77b7121c4b17d57b4d9000e1f239841f8dc3', 60
);
