INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'signal-extraction#5', 'signal-extraction', 5, 'Remove',
  '## Remove

- marketing and calls to action;
- biography and stage banter;
- repeated examples without new meaning;
- vague motivation;
- long quotes;
- full transcripts;
- personal stories unless they encode transferable workflow patterns.', 'bdde8248dd5f3358a6f1e194082acc15cbfd03d3e7426fd4afdd17a6c573b599', 50
);
