INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'tailscale-private-device-access-for-local-agents#11', 'tailscale-private-device-access-for-local-agents', 11, 'Agent environment compatibility',
  '## Agent environment compatibility

- Agent platforms: Codex-native local agents and Pritha descendants.
- Runtime environment: local Mac, Mac mini, phone browser and laptop browser inside the same tailnet.
- Config surfaces: operations manifest, deployment scripts, README/operator guide and optional launchd plist.
- Portability: environment-specific.
- Codex adaptation: make Tailscale a selected operations/network module, not an implicit default for every descendant.
- Environment-specific caveats: Tailscale CLI syntax and Serve behavior can change; verify on the host before recording a URL as ready.', '28a5a9e5930341ba26d700288aed0b59d8cdf5018e666b30b8f87ccfcc32979d', 111
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Agent environment compatibility

