INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'tailscale-private-device-access-for-local-agents#13', 'tailscale-private-device-access-for-local-agents', 13, 'Examples',
  '## Examples

- FESPA26: local Mac-hosted voice/reportage workbench reachable from MacBook or phone through Tailscale.
- Funny Teacher: local Next.js voice learning app served through Tailscale HTTPS so phone microphone/browser access works inside the trusted tailnet.
- Techscope Web: private knowledge UI opened from MacBook or phone without public publishing.', 'f838c80593f85deba8604870de259faa9bee9c4e547cc54416b725b8c55c3091', 68
);
