INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'techscope-quality-and-release-roadmap#63', 'techscope-quality-and-release-roadmap', 63, 'Target structure',
  '### Target structure

```text
scripts/agents-mother/
  index.mjs              # CLI entry, re-exports current commands
  contract.mjs           # parse, validate, init, interview
  research.mjs
  scaffold/
    index.mjs
    templates/           # generated file templates as separate modules
      smoke-test.template.mjs
      interface-status.template.mjs
      ...
  test.mjs
  handoff.mjs
  operations.mjs
  registry.mjs
scripts/agents-mother.mjs # thin wrapper → import ''./agents-mother/index.mjs''
```', '5aedb89a0d028ae83342419f1705e95ec3a80430d7ffa98960380fc0986c1530', 60
);
