INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'agent-mcp-connector-selection#2', 'agent-mcp-connector-selection', 2, 'Goal',
  '## Goal

Choose whether a Pritha-created child agent needs MCP connectors, and if so,
record them as explicit, scoped, auditable harness modules rather than implicit
global tools.', '4f98fa0372fccd9aa0e883bd3ac6ba17d4244795a4b37d3bd4ece1ab1f177471', 37
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Goal

