INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'agent-skill-pack-selection#4', 'agent-skill-pack-selection', 4, 'Verification',
  '## Verification

- `node scripts/pritha.mjs skills status`
- `node scripts/pritha.mjs skills select <contract-path>`
- In a child scaffold: `node scripts/skills-status.mjs`
- Full Pritha regression: `npm test --silent`
- Privacy/supply-chain gate: `node scripts/privacy-audit.mjs --strict`', 'd49bffba3e94c08d79fcfa15e411f56cfcce6db0ff53c0f12ce45691eee7be99', 45
);
