Status: accepted, retrospective', 'Agent Project Contract: FESPA26', '2026-05-25-fespa26-agent-contract', '2026-05-25-fespa26-agent-contract#1');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-fespa26-agent-contract#2', '2026-05-25-fespa26-agent-contract', 2, 'Purpose',
  '## Purpose

- Agent name: FESPA26
- Primary mission: voice-first Codex-native workbench for processing FESPA 2026 booth media, notes, links and files into a bilingual mobile news feed
- Target user: one operator working with exhibition materials.
- Success criteria: the operator can talk to the agent, upload or paste media/materials, queue heavier Codex processing, review bilingual feed cards and publish only after explicit approval.
- Out of scope: multi-user tenancy, public publishing without confirmation, Telegram adapter in v1, autonomous background heartbeat, automatic launchd service install.', 'd301462b9c1c75f20a917f4a24844f63315dee68d707077a4166bf1dcc2d14e9', 117
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Purpose

- Agent name: FESPA26
- Primary mission: voice-first Codex-native workbench for processing FESPA 2026 booth media, notes, links and files into a bilingual mobile news feed
- Target user: one operator working with exhibition materials.
- Success criteria: the operator can talk to the agent, upload or paste media/materials, queue heavier Codex processing, review bilingual feed cards and publish only after explicit approval.
- Out of scope: multi-user tenancy, public publishing without confirmation, Telegram adapter in v1, autonomous background heartbeat, automatic launchd service install.', 'Purpose', '2026-05-25-fespa26-agent-contract', '2026-05-25-fespa26-agent-contract#2');

