INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-fespa26-agent-contract#7', '2026-05-25-fespa26-agent-contract', 7, 'Runtime And Interface',
  '## Runtime And Interface

- Runtime family: hybrid, with Codex-native sidecar.
- Primary interface: web.
- Secondary interfaces: CLI maintenance scripts.
- Telegram mode: none.
- Expected hosting: local Mac, accessible from MacBook or phone through Tailscale.', 'dbd2186ac9e77db8de0455993108c8dcf601695db5772f4e15314baac172f6b5', 50
);
