INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-fespa26-agent-contract#9', '2026-05-25-fespa26-agent-contract', 9, 'Proactivity',
  '## Proactivity

- Proactive mode: manual.
- Trigger sources: voice command, UI ingest form, local CLI command.
- Schedule: none.
- Heartbeat interval: none.
- Idle behavior: wait for operator action.
- User interruption policy: do not interrupt unless configured later.', '6227413fbbb5085a79336d88015505c6383dc3350d9fcc3a263bf47952d75edd', 56
);
