INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-funny-teacher-agent-contract#2', '2026-05-25-funny-teacher-agent-contract', 2, 'Purpose',
  '## Purpose

- Agent name: Funny Teacher
- Primary mission: help one user quickly and enjoyably improve English, mainly speaking, by turning YouTube lessons into interactive voice practice, comprehension checks, correction and spaced review.
- Target user: one learner who watches English-learning YouTube videos and then practices the lesson with a voice agent.
- Success criteria: after a lesson, the agent can judge whether the learner understood the video material, can speak the target patterns, can correct mistakes, and can decide whether to repeat, drill or move to another lesson.
- Out of scope for v1: multi-user classroom, public course marketplace, paid licensing, formal exam certification, automatic social publishing.', 'd9d71360936db0e27dc5a6579eeab979c1f7f2b778f9a930014d54c33af79ab7', 148
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Purpose

- Agent name: Funny Teacher
- Primary mission: help one user quickly and enjoyably improve English, mainly speaking, by turning YouTube lessons into interactive voice practice, comprehension checks, correction and spaced review.
- Target user: one learner who watches English-learning YouTube videos and then practices the lesson with a voice agent.
- Success criteria: after a lesson, the agent can judge whether the learner understood the video material, can speak the target patterns, can correct mistakes, and can decide whether to repeat, drill or move to another lesson.
- Out of scope for v1: multi-user classroom, public course marketplace, paid licensing, formal exam certification, automatic social publishing.', 'Purpose', '2026-05-25-funny-teacher-agent-contract', '2026-05-25-funny-teacher-agent-contract#2');

