INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-funny-teacher-agent-contract#10', '2026-05-25-funny-teacher-agent-contract', 10, 'Operations And Service',
  '## Operations And Service

