INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-funny-teacher-agent-contract#11', '2026-05-25-funny-teacher-agent-contract', 11, 'Proactivity',
  '## Proactivity

- Proactive mode: manual in v1.
- Trigger sources: user opens lesson, user starts voice practice, user asks for review.
- Schedule: none in v1.
- Heartbeat interval: none.
- Idle behavior: wait for learner action.
- User interruption policy: do not interrupt. Future spaced-repetition reminders require explicit opt-in.', '526cfcba4f1c9b6f37ec284c51e4b7ebdd46969a27d77ccc3db35c267c8a0178', 69
);
