INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-06-12-stupidjoke-agent-contract#7', '2026-06-12-stupidjoke-agent-contract', 7, 'Critical User Workflows',
  '### Critical User Workflows

- Operator starts the local project in a writable sibling folder.
- Operator adds or edits sample jokes in `fixtures/user_import/jokes.jsonl`.
- Healthcheck validates fixture format.
- Smoke test runs safety examples and realtime event examples.
- Voice/control-center event asks for a joke.
- Handler selects/generates a short safe joke or gives a safe fallback.
- Unsafe imported material is rejected with a reason and is not promoted to curated examples.', 'eb4995e43574b90f0f759817aebc69bc58491a7f0b9c23cf0aec551acd33de7f', 100
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
