INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'child-agent-profile-fespa26#2', 'child-agent-profile-fespa26', 2, 'Purpose',
  '## Purpose

- Voice-first Codex-native workbench for processing FESPA 2026 booth media,
  notes, links and files into a bilingual mobile news feed.
- Current Pritha role: reference descendant for event, exhibition, media and
  reportage workflows.', '842c48308862ab6e1807da04acc85c330db760086ae4a4f14628f0f51324cff2', 48
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Purpose

- Voice-first Codex-native workbench for processing FESPA 2026 booth media,
  notes, links and files into a bilingual mobile news feed.
- Current Pritha role: reference descendant for event, exhibition, media and
  reportage workflows.', 'Purpose', 'child-agent-profile-fespa26', 'child-agent-profile-fespa26#2');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'child-agent-profile-fespa26#3', 'child-agent-profile-fespa26', 3, 'Current Capabilities',
  '## Current Capabilities

- Realtime voice interaction through a browser UI.
- Event/source intake into SQLite operational memory.
- Feed-card workflow with explicit publication gate.
- Codex deep-task boundary for heavier processing, verification and system
  tasks.
- Local queue fallback when foreground Codex transport is unavailable.', '3410835ee318c8886a10c8295ec74db4334a051c49bbdc0137d1cc9cdbeec774', 63
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Current Capabilities

- Realtime voice interaction through a browser UI.
- Event/source intake into SQLite operational memory.
- Feed-card workflow with explicit publication gate.
- Codex deep-task boundary for heavier processing, verification and system
  tasks.
- Local queue fallback when foreground Codex transport is unavailable.', 'Current Capabilities', 'child-agent-profile-fespa26', 'child-agent-profile-fespa26#3');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'child-agent-profile-fespa26#4', 'child-agent-profile-fespa26', 4, 'Interfaces',
  '## Interfaces

- Primary: web UI.
- Secondary: CLI maintenance scripts.
- Telegram: absent.
- Tailscale: used for trusted device access in local operator setup.', '6d76ba135c2e356ebff962b7c93dea2041f46e4f516a312e85a596328e07b706', 34
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Interfaces

