INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'child-agent-profile-fespa26#7', 'child-agent-profile-fespa26', 7, 'Operations',
  '## Operations

- Deployment target: local Mac.
- Service mode: manual.
- Autostart: disabled.
- Local upstream observed by operations manifest: `http://127.0.0.1:3027`.
- Healthcheck command is defined in the child operations manifest.', '25682fc4237a765360b283d2ba9537d03781b81da59e1932cbe924522971990b', 44
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Operations

- Deployment target: local Mac.
- Service mode: manual.
- Autostart: disabled.
- Local upstream observed by operations manifest: `http://127.0.0.1:3027`.
- Healthcheck command is defined in the child operations manifest.', 'Operations', 'child-agent-profile-fespa26', 'child-agent-profile-fespa26#7');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'child-agent-profile-fespa26#8', 'child-agent-profile-fespa26', 8, 'Known Issues',
  '## Known Issues

- Snapshot metadata store is not present, so rollback is unavailable.
- Pritha lifecycle version is `v1`; no separate child app semantic version has
  been recorded in the current curated memory.', 'b58e7492dff5038d03ec2188fc7c8ceaba2e3444408798ea65f376f4d58d2d67', 46
);
