INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'child-agent-profile-funny-teacher#2', 'child-agent-profile-funny-teacher', 2, 'Purpose',
  '## Purpose

- Help one user improve spoken English through YouTube lesson intake,
  realtime voice practice, correction and spaced review.
- Current Pritha role: accepted reference example for feedback-driven voice
  learning agents.', '3724763495f207d2fbabb91e92d015999d3615daf8d3629608958a253406e512', 44
);
