INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'child-agent-profile-funny-teacher#3', 'child-agent-profile-funny-teacher', 3, 'Current Capabilities',
  '## Current Capabilities

- Web voice learning flow.
- YouTube lesson intake with idempotent source behavior.
- Realtime teacher session.
- Learner attempts and outcomes stored in durable memory.
- Semantic search with lexical fallback.
- User-visible memory search and selected practice focus.', '1456bd152e9753320995273063467697025185c0d94e56855340700e52091751', 59
);
