INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-funny-teacher-agent-deployment-report#3', '2026-05-25-funny-teacher-agent-deployment-report', 3, 'Deployment Surface',
  '## Deployment Surface

- Local upstream: `http://127.0.0.1:3033`
- Tailscale HTTPS URL: `https://ivans-mac-mini.tail691439.ts.net:3034`
- Proxy command: `tailscale serve --bg --https=3034 http://127.0.0.1:3033`
- Service mode: manual
- Autostart: disabled
- Network boundary: trusted Tailscale network only', 'b1724fadb32e1dcfbc4b7448e4fbfa7fa8547f2d0e27e9c32f3a3bf0573babe9', 46
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Deployment Surface

- Local upstream: `http://127.0.0.1:3033`
- Tailscale HTTPS URL: `https://ivans-mac-mini.tail691439.ts.net:3034`
- Proxy command: `tailscale serve --bg --https=3034 http://127.0.0.1:3033`
- Service mode: manual
- Autostart: disabled
- Network boundary: trusted Tailscale network only', 'Deployment Surface', '2026-05-25-funny-teacher-agent-deployment-report', '2026-05-25-funny-teacher-agent-deployment-report#3');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-25-funny-teacher-agent-deployment-report#4', '2026-05-25-funny-teacher-agent-deployment-report', 4, 'Implemented In Funny Teacher',
  '## Implemented In Funny Teacher

- Updated `operations/manifest.json` with Tailscale URL and proxy command.
- Added `scripts/tailscale-serve.mjs`.
- Added npm commands:
  - `npm run tailscale:serve`
  - `npm run tailscale:status`
- Updated `.env.local` machine-specific URL values without exposing secrets.
- Updated README and operator guide.', '8b6fb6321245a00dde335bc1da4e993d87f1a9850402126c8bf0aeed1fc1f222', 60
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Implemented In Funny Teacher

- Updated `operations/manifest.json` with Tailscale URL and proxy command.
- Added `scripts/tailscale-serve.mjs`.
- Added npm commands:
  - `npm run tailscale:serve`
  - `npm run tailscale:status`
- Updated `.env.local` machine-specific URL values without exposing secrets.
- Updated README and operator guide.', 'Implemented In Funny Teacher', '2026-05-25-funny-teacher-agent-deployment-report', '2026-05-25-funny-teacher-agent-deployment-report#4');

