INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-26-funny-teacher-learning-memory-operations-report#3', '2026-05-26-funny-teacher-learning-memory-operations-report', 3, 'Implemented',
  '## Implemented

- Added `lesson_completions` table for final lesson results.
- Extended Realtime tool `set_lesson_outcome` to save:
  - outcome;
  - grade;
  - teacher summary;
  - strengths;
  - weaknesses;
  - next review hint/date.
- Added repeat lesson API: `POST /api/lessons/[id]/repeat`.
- Updated Realtime teacher instructions:
  - teach any target language, not English only;
  - cover comprehension, targets and free-speaking/role-play before final grade;
  - compare repeated attempts with previous completions.
- Changed UI heading to voice language practice.
- Replaced technical Semantic Search test with user-facing `Find in memory`.
- Added media cache cleanup:
  - `.wav` files are temporary after ASR;
  - `.mp4` files are cache;
  - source of truth remains URL, transcript, lesson derivative, attempts, grade and progress.', '86776f351b3143e0e5ad8e7d32092e78d2d8e61acbc9dae7faceb5ce8b0875d7', 158
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Implemented

- Added `lesson_completions` table for final lesson results.
- Extended Realtime tool `set_lesson_outcome` to save:
  - outcome;
  - grade;
  - teacher summary;
  - strengths;
  - weaknesses;
  - next review hint/date.
- Added repeat lesson API: `POST /api/lessons/[id]/repeat`.
- Updated Realtime teacher instructions:
  - teach any target language, not English only;
  - cover comprehension, targets and free-speaking/role-play before final grade;
  - compare repeated attempts with previous completions.
- Changed UI heading to voice language practice.
- Replaced technical Semantic Search test with user-facing `Find in memory`.
- Added media cache cleanup:
  - `.wav` files are temporary after ASR;
  - `.mp4` files are cache;
  - source of truth remains URL, transcript, lesson derivative, attempts, grade and progress.', 'Implemented', '2026-05-26-funny-teacher-learning-memory-operations-report', '2026-05-26-funny-teacher-learning-memory-operations-report#3');

