INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-pritha-github-publish-and-push-handoff-report#3', '2026-05-28-pritha-github-publish-and-push-handoff-report', 3, 'Changes Made',
  '## Changes Made

- Added `docs/github-publish-and-push.md`.
- Linked the checklist from `README.md`, `docs/release.md` and
  `docs/contributing-workflow.md`.
- Added GitHub push/release rules to `AGENTS.md` so future Codex threads know
  which checks to run before pushing.', '0447a22b21cdc098e1f2f03773add186de15cdb19b18331974809814b63b51ff', 45
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Changes Made

- Added `docs/github-publish-and-push.md`.
- Linked the checklist from `README.md`, `docs/release.md` and
  `docs/contributing-workflow.md`.
- Added GitHub push/release rules to `AGENTS.md` so future Codex threads know
  which checks to run before pushing.', 'Changes Made', '2026-05-28-pritha-github-publish-and-push-handoff-report', '2026-05-28-pritha-github-publish-and-push-handoff-report#3');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-pritha-github-publish-and-push-handoff-report#4', '2026-05-28-pritha-github-publish-and-push-handoff-report', 4, 'Human GitHub Actions Still Required',
  '## Human GitHub Actions Still Required

- Approve replacing the initial GitHub-created `LICENSE` commit with local Pritha history.
- Push `main` and tag `v0.1.0`.
- Verify CI, configure `main` protection, create GitHub Release and only then
  make the repository public.', '7c100d4bf74b78a8d10328139b5499dba77bb23d790bc2ca6cc9ace77f8da7ad', 54
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Human GitHub Actions Still Required

- Approve replacing the initial GitHub-created `LICENSE` commit with local Pritha history.
