INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-github-release-status-gate-report#4', '2026-05-28-techscope-github-release-status-gate-report', 4, 'Verification',
  '## Verification

| Command | Result | Notes |
| --- | --- | --- |
| `node scripts/github-release-status.mjs --json --skip-pre-push-audit --skip-working-tree-check` | pass / `pending-external` | Local docs/workflows are present; origin remote, tag and live CI/release proof are missing. |
| `npm test --silent` | pass | 38/38 tests passed, including release-status tests. |', 'be4c754f72a9ed941b52bfd4bba81abbbd74a8e61d052eb6db90d0c8943fa726', 75
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Verification

