INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-0-baseline-report#13', '2026-05-28-techscope-quality-phase-0-baseline-report', 13, 'AM-CANDIDATE patterns',
  '## AM-CANDIDATE patterns

- `audit-baseline-report`: every roadmap phase gets a structured report with evidence.
- `golden-checks-manifest`: one green/red command wraps project health.
- `audit-log-append-only`: roadmap execution becomes inspectable history.
- `non-mutating-self-inspection`: health checks should not create durable reports by default.', '7f3ab15015b1594b28bf56f9c761eda4dc63e6dd82c9c4173489bdaea84aa01d', 54
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## AM-CANDIDATE patterns

- `audit-baseline-report`: every roadmap phase gets a structured report with evidence.
- `golden-checks-manifest`: one green/red command wraps project health.
- `audit-log-append-only`: roadmap execution becomes inspectable history.
- `non-mutating-self-inspection`: health checks should not create durable reports by default.', 'AM-CANDIDATE patterns', '2026-05-28-techscope-quality-phase-0-baseline-report', '2026-05-28-techscope-quality-phase-0-baseline-report#13');

