INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-12-first-run-setup-report#8', '2026-05-28-techscope-quality-phase-12-first-run-setup-report', 8, 'AM-CANDIDATE patterns',
  '## AM-CANDIDATE patterns

- `first-run-setup-workflow`: Codex-dialog bootstrap with CLI fallback.
- `trigger-phrase-routing`: deterministic mapping from user phrases to workflows.
- `completed-with-warnings-status`: first-run setup does not dead-end on noncritical checks.
- `secrets-collector-pattern`: private local env write with masked status.
- `minimal-default-config`: Codex-only setup as the safest starting point.', '8746730c0f64d4e8a01cfa14ffa5abd3eba32056a991c81a52c1090b2dd54452', 64
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## AM-CANDIDATE patterns

- `first-run-setup-workflow`: Codex-dialog bootstrap with CLI fallback.
- `trigger-phrase-routing`: deterministic mapping from user phrases to workflows.
- `completed-with-warnings-status`: first-run setup does not dead-end on noncritical checks.
- `secrets-collector-pattern`: private local env write with masked status.
- `minimal-default-config`: Codex-only setup as the safest starting point.', 'AM-CANDIDATE patterns', '2026-05-28-techscope-quality-phase-12-first-run-setup-report', '2026-05-28-techscope-quality-phase-12-first-run-setup-report#8');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-12-first-run-setup-report#9', '2026-05-28-techscope-quality-phase-12-first-run-setup-report', 9, 'Open questions',
  '## Open questions

- Should a future Phase 14 pattern review promote this setup wizard into the default Pritha descendant scaffold?
- Should first-run setup optionally create the first descendant contract, or remain strictly environment/bootstrap only?', '0a1a2ada652890b4b8dfb80f76dd9ff8245f79765d4b479543ebd0a2498e986f', 49
