INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-28-techscope-quality-phase-9d-agents-mother-command-modules-report#7', '2026-05-28-techscope-quality-phase-9d-agents-mother-command-modules-report', 7, 'AM-CANDIDATE patterns',
  '## AM-CANDIDATE patterns

- `isolated-root-command-module-test`: use `TECHSCOPE_ROOT` with a temp project
  to test report-writing command modules without polluting real memory.
- `lifecycle-command-modules`: handoff, operations, deployment, evolve and
  registry are separate from CLI dispatch.
- `legacy-entrypoint-thin-tail`: the entrypoint can shrink safely while older
  interview/research logic remains stable.', 'b2f0b9f48f4ceb7b5291243814f377bcfafcb89a0510a5070dfdce83020c0658', 63
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## AM-CANDIDATE patterns

- `isolated-root-command-module-test`: use `TECHSCOPE_ROOT` with a temp project
  to test report-writing command modules without polluting real memory.
- `lifecycle-command-modules`: handoff, operations, deployment, evolve and
  registry are separate from CLI dispatch.
- `legacy-entrypoint-thin-tail`: the entrypoint can shrink safely while older
  interview/research logic remains stable.', 'AM-CANDIDATE patterns', '2026-05-28-techscope-quality-phase-9d-agents-mother-command-modules-report', '2026-05-28-techscope-quality-phase-9d-agents-mother-command-modules-report#7');

