INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  '2026-05-19-fespa26-agent-research#16', '2026-05-19-fespa26-agent-research', 16, 'Standard: agent-creation-harness',
  '### Standard: agent-creation-harness

- Path: 04_standards/agent-creation-harness.md
- Basis: Every new agent created by TechScope must start from an explicit `agent-contract` and must be delivered as a working, testable scaffold with a documented harness. TechScope may use its own architecture as a reference, but it must not clone itself blindly. The new agent''s runtime, interface, memory, tools and security model must follow the contract.', '2458401bb7343fa40e887b157fded11f532b575b6675c548df292198cb1de906', 86
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
