INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'skill-evidence-classification#2', 'skill-evidence-classification', 2, 'When to Use',
  '## When to Use

Use when converting a source, user note, transcript, article, repository or external claim into curated agent knowledge.', '1bf3ad623824b079818f5b9e276496ed891a280ea3ad0625e3a238029ba27c6a', 29
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## When to Use

Use when converting a source, user note, transcript, article, repository or external claim into curated agent knowledge.', 'When to Use', 'skill-evidence-classification', 'skill-evidence-classification#2');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'skill-evidence-classification#3', 'skill-evidence-classification', 3, 'Procedure',
  '## Procedure

1. Separate facts, opinions, marketing claims, hypotheses and unknowns.
2. Prefer primary sources for volatile technical claims.
3. Record source date, retrieved date, verified date and version context when available.
4. Compare the claim with existing briefs, reviews, decisions and standards.
5. Promote only well-supported, reusable conclusions into standards or decisions.', '734ce0b6a5db39645b3ce9ec3f284b33361eeeac631e1aaa5770d9dbad9a7750', 72
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Procedure

1. Separate facts, opinions, marketing claims, hypotheses and unknowns.
2. Prefer primary sources for volatile technical claims.
3. Record source date, retrieved date, verified date and version context when available.
4. Compare the claim with existing briefs, reviews, decisions and standards.
5. Promote only well-supported, reusable conclusions into standards or decisions.', 'Procedure', 'skill-evidence-classification', 'skill-evidence-classification#3');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'skill-evidence-classification#4', 'skill-evidence-classification', 4, 'Pitfalls',
  '## Pitfalls

- Do not treat generated wiki pages as evidence.
- Do not collapse "interesting" and "adopt now" into the same recommendation.
- Do not hide weak evidence behind confident language.', 'c3249c813ad85b5b82c4c70f952ca1ea3e46944a23fc1a7b02e3278eb03c76f4', 44
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Pitfalls

- Do not treat generated wiki pages as evidence.
- Do not collapse "interesting" and "adopt now" into the same recommendation.
- Do not hide weak evidence behind confident language.', 'Pitfalls', 'skill-evidence-classification', 'skill-evidence-classification#4');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'skill-evidence-classification#5', 'skill-evidence-classification', 5, 'Verification',
  '## Verification

- Evidence quality is stated.
- Alternatives or trade-offs are named.
- Open questions remain explicit.
- Techscope/Agents Mother fit is recorded when relevant.', 'fbd3d4ca87992a805d587a8ef3d60871e50d800e8840d490924871a78f1d6fc1', 36
);
