INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## When to Use

Use when an agent needs to add or revise durable memory in Markdown files.', 'When to Use', 'skill-markdown-memory-update', 'skill-markdown-memory-update#2');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'skill-markdown-memory-update#3', 'skill-markdown-memory-update', 3, 'Procedure',
  '## Procedure

1. Keep raw material separate from curated knowledge.
2. Add YAML frontmatter to every new curated Markdown artifact.
3. Link sources, related artifacts, superseded artifacts and replacement artifacts when known.
4. Keep generated navigation or wiki pages out of the authoritative decision path.
5. Rebuild or validate indexes only after Markdown source files are coherent.', '2623d2a57315d54322f157f99030788d60dece33456de1c1320788c02d39cad4', 77
);
INSERT INTO chunks_fts (text, heading, document_id, chunk_id)
VALUES ('## Procedure

1. Keep raw material separate from curated knowledge.
2. Add YAML frontmatter to every new curated Markdown artifact.
3. Link sources, related artifacts, superseded artifacts and replacement artifacts when known.
4. Keep generated navigation or wiki pages out of the authoritative decision path.
5. Rebuild or validate indexes only after Markdown source files are coherent.', 'Procedure', 'skill-markdown-memory-update', 'skill-markdown-memory-update#3');

INSERT INTO chunks (id, document_id, ordinal, heading, text, hash, token_count)
VALUES (
  'skill-markdown-memory-update#4', 'skill-markdown-memory-update', 4, 'Pitfalls',
  '## Pitfalls

- Do not store secrets in memory.
- Do not treat SQLite, embeddings or generated wiki as the canonical authored source.
- Do not rewrite unrelated memory files as cleanup during a narrow update.', '500728a88fd5f22dacdc227d07eed01ece1b13e5d7b72c842330c2c68b2f4128', 49
);
